function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3800)}
function script(url){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=url;s.onload=resolve;s.onerror=()=>{s.remove();reject(new Error(url))};document.head.appendChild(s)})}
async function dependency(path){try{await script('https://cdn.jsdelivr.net/npm/three@0.128.0/'+path)}catch{await script('https://unpkg.com/three@0.128.0/'+path)}}
function mat(color,opt={}){const key=color+JSON.stringify(opt);if(!materialCache.has(key))materialCache.set(key,new THREE.MeshStandardMaterial({color,roughness:.9,metalness:0,...opt}));return materialCache.get(key)}
function geo(type){if(!geometryCache.has(type))geometryCache.set(type,type==='box'?new THREE.BoxGeometry(1,1,1):type==='cyl'?new THREE.CylinderGeometry(1,1,1,12):new THREE.IcosahedronGeometry(1,1));return geometryCache.get(type)}
function box(g,x,y,z,w,h,d,c,options={}){const shape=renderer?.isSoftware&&Math.max(w,h,d)>8?new THREE.BoxGeometry(1,1,1,Math.max(1,Math.ceil(w/4)),Math.max(1,Math.ceil(h/3)),Math.max(1,Math.ceil(d/4))):geo('box');const mesh=new THREE.Mesh(shape,typeof c==='string'?mat(c,options):c);mesh.position.set(x,y,z);mesh.scale.set(w,h,d);g.add(mesh);return mesh}
function cyl(g,x,y,z,r,h,c){const m=new THREE.Mesh(geo('cyl'),mat(c));m.position.set(x,y,z);m.scale.set(r,h,r);g.add(m);return m}
function ball(g,x,y,z,r,c){const m=new THREE.Mesh(geo('ball'),mat(c));m.position.set(x,y,z);m.scale.setScalar(r);g.add(m);return m}
function group(g,x=0,y=0,z=0,rot=0){const q=new THREE.Group();q.position.set(x,y,z);q.rotation.y=rot;g.add(q);return q}
function obstacle(x,z,w,d){colliders.push({x,z,w,d})}
function solid(g,x,y,z,w,h,d,c){const b=box(g,x,y,z,w,h,d,c);obstacle(x,z,w,d);return b}
function sign(g,text,x,y,z,w=2,h=.4,rot=0,bg='#f9f5e9',color='#354d44',floor=false){const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=Math.max(128,Math.round(1024*h/w));const ctx=canvas.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle=color;ctx.textAlign='center';ctx.textBaseline='middle';const lines=text.split('\n');ctx.font=`600 ${Math.min(96,Math.round(canvas.height/(lines.length+1.1)))}px "Malgun Gothic",sans-serif`;lines.forEach((s,i)=>ctx.fillText(s,512,canvas.height*(i+.5)/lines.length,970));const tex=new THREE.CanvasTexture(canvas);tex.encoding=THREE.sRGBEncoding;const mesh=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({map:tex,side:THREE.DoubleSide}));mesh.position.set(x,y,z);mesh.rotation.y=rot;if(floor){mesh.rotation.x=-Math.PI/2;mesh.userData.canvasLayer=-79;}g.add(mesh);return mesh}
async function loadBrand(){brandImage=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('센터 로고를 불러오지 못했습니다.'));img.src=window.DDC_CENTER_LOGO_DATA||ASSET+'ddc_center_logo.png';});}
async function loadRelatedMedia(){await Promise.all(Object.keys(relatedMedia).map(id=>new Promise(resolve=>{const img=new Image();img.onload=()=>{tenantImages.set(id,img);resolve();};img.onerror=()=>{console.warn('업체 이미지 로드 실패:',id);resolve();};img.src=window.DDC_CENTER_RELATED_IMAGES?.[id]||ASSET+relatedMedia[id].file;})));}
function companyScreenMaterial(id){if(screenMaterials.has(id))return screenMaterials.get(id);const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=576;const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,1024,576);const image=tenantImages.get(id);if(image){const scale=Math.min(1024/image.width,576/image.height),w=image.width*scale,h=image.height*scale;ctx.drawImage(image,(1024-w)/2,(576-h)/2,w,h);}else{ctx.fillStyle='#263d38';ctx.font='48px "Malgun Gothic",sans-serif';ctx.textAlign='center';ctx.fillText(companyProfiles[id]?.companyName||'',512,288,970);}const texture=new THREE.CanvasTexture(canvas);texture.encoding=THREE.sRGBEncoding;const material=new THREE.MeshBasicMaterial({map:texture,toneMapped:false});screenMaterials.set(id,material);return material;}
function companyMonitor(g,id,z=-.096){if(!relatedMedia[id])return;const screen=new THREE.Mesh(new THREE.PlaneGeometry(.51,.29),companyScreenMaterial(id));screen.position.set(0,1.09,z);screen.userData.companyId=id;g.add(screen);}
function logoSign(g,x,y,z,w=3.3,h=.34,rot=0,bg='#faf8f1',floor=false,caption=''){const canvas=document.createElement('canvas');canvas.width=2048;canvas.height=Math.max(128,Math.round(2048*h/w));const ctx=canvas.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,canvas.width,canvas.height);if(brandImage){const scale=Math.min(canvas.width*.94/brandImage.width,canvas.height*(caption?.48:.86)/brandImage.height),iw=brandImage.width*scale,ih=brandImage.height*scale;const cy=canvas.height*(caption?.36:.5);ctx.drawImage(brandImage,(canvas.width-iw)/2,cy-ih/2,iw,ih);}if(caption){ctx.fillStyle='#405b4b';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='500 '+Math.min(96,Math.round(canvas.height*.16))+'px "Malgun Gothic",sans-serif';ctx.fillText(caption,canvas.width/2,canvas.height*.8,canvas.width*.92);}const texture=new THREE.CanvasTexture(canvas);texture.encoding=THREE.sRGBEncoding;const mesh=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({map:texture,side:THREE.DoubleSide,toneMapped:false}));mesh.position.set(x,y,z);mesh.rotation.y=rot;if(floor){mesh.rotation.x=-Math.PI/2;mesh.userData.canvasLayer=-79;}mesh.userData.centerLogo=true;g.add(mesh);return mesh;}
