function glazing(axis,fixed,a,b){const len=b-a,mid=(a+b)/2;const x=axis==='z'?fixed:mid,z=axis==='z'?mid:fixed,w=axis==='z'?.13:len,d=axis==='z'?len:.13;solid(low,x,.34,z,w,.68,d,'#ece8db');box(upper,x,2.89,z,w,.22,d,'#d9d7cc');box(upper,x,1.75,z,axis==='z'?.025:len,2.05,axis==='z'?len:.025,'#a9cbd3',{transparent:true,opacity:.28,depthWrite:false});for(let n=0;n<=Math.ceil(len/1.5);n++){const p=a+len*n/Math.ceil(len/1.5);box(upper,axis==='z'?fixed:p,1.76,axis==='z'?p:fixed,axis==='z'?.1:.06,2.07,axis==='z'?.06:.1,'#344e53')}box(upper,x,1.25,z,w,.045,d,'#536c6c');for(let n=0;n<4;n++)box(upper,x,2.73-n*.11,z,axis==='z'?.1:len,.07,axis==='z'?len:.1,'#d9ded8');}
